"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFaqContent } from "./components/faq-blocks/content";
import View4 from "./components/faq-blocks/variants/05-search";
const variants = {"search":View4};
export type { ArtemisFaqContact, ArtemisFaqContent, ArtemisFaqLink, ArtemisFaqQuestion, ArtemisFaqSearch } from "./components/faq-blocks/content";
export interface ArtemisFaqBlocksProps { className?: string; variant?: "search"; /** The words on the FAQ section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFaqContent>; }
export function ArtemisFaqBlocks({ className, variant = "search", content }: ArtemisFaqBlocksProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal

/** The words on a button or link, and where it goes. */
export interface ArtemisFaqLink {
  label: string;
  href: string;
}

/** A question and its answer. */
export interface ArtemisFaqQuestion {
  /** The question, on the row that opens. */
  question: string;
  /** The answer, shown while the row is open. */
  answer: string;
  /** A short slug, unique in the list, used in the row's element ids. Defaults to the row's position. */
  id?: string;
  /** The topic it belongs to. search shows it on the row and adds a filter tab for each topic, in the order the topics first appear; with no topics it shows no tabs. */
  category?: string;
}

/** A card beside the questions that points to a person. */
export interface ArtemisFaqContact {
  /** A small line over the title. split. */
  label?: string;
  /** The card's heading. */
  title: string;
  /** The paragraph under the heading. */
  description: string;
  /** The card's button. */
  cta: ArtemisFaqLink;
}

/** The words on the search box, its topic tabs and its empty result. */
export interface ArtemisFaqSearch {
  /** The hint in the empty search box. */
  placeholder: string;
  /** The first topic tab, which shows every question. */
  allLabel: string;
  /** The heading shown when no question matches. */
  emptyTitle: string;
  /** The line under that heading. */
  emptyText: string;
}

/** The words on an Artemis FAQ section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisFaqContent {
  /** The short line above the heading. All layouts. */
  badge: string;
  /** The heading. All layouts. */
  headline: string;
  /** The heading's last words. stacked underlines them; the other layouts run them on after `headline`. Left out, it keeps the layout's own only when `headline` is left out too. */
  headlineAccent?: string;
  /** The paragraph under the heading. All layouts. */
  subhead: string;
  /** The questions, each opening to show its answer. All layouts. numbered and split number them; numbered, ai-workspace, split and search open one at a time, starting with the first; stacked opens any number, starting with the first two. */
  questions: ArtemisFaqQuestion[];
  /** A card with a button beside the questions. ai-workspace and split. */
  contact?: ArtemisFaqContact;
  /** The words on the search box, the topic tabs and the empty result. search. */
  search?: ArtemisFaqSearch;
}

"use client";
// @zeus-internal
import { useId, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { ArtemisSegmentedTabs } from "../../../foundations/segmented-tabs";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { SearchAccordion } from "./05-search/accordion";
import { defaultQuestions } from "./05-search/items";
import type { ArtemisFaqContent } from "../content";
const DEFAULT = {
    badge: "Help center",
    headline: "How can we help?",
    subhead: "Search the most common questions or browse by topic.",
    questions: defaultQuestions,
    search: {
        placeholder: "Search questions",
        allLabel: "All",
        emptyTitle: "No matching questions",
        emptyText: "Try a shorter search or choose another topic.",
    },
} satisfies ArtemisFaqContent;
/** The value of the tab that shows every topic; topics come from the questions, which never give an empty one. */
const ALL = "";
const hidden = { opacity: 0, filter: "blur(8px)", y: 18 };
const shown = { opacity: 1, filter: "blur(0px)", y: 0 };
export default function FaqBlocksSearch({ content }: { content?: Partial<ArtemisFaqContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const items = copy.questions.map((item, index) => ({ ...item, id: item.id ?? `q${index}` }));
    const topics = [...new Set(items.flatMap(item => item.category ? [item.category] : []))];
    const reduced = useReducedMotion();
    const inputId = useId();
    const inputRef = useRef<HTMLInputElement>(null);
    const [query, setQuery] = useState("");
    const [topic, setTopic] = useState(ALL);
    const [focused, setFocused] = useState(false);
    const search = query.trim().toLowerCase();
    const filtered = items.filter(item => (topic === ALL || item.category === topic) &&
        (!search || `${item.question} ${item.answer}`.toLowerCase().includes(search)));
    return (<section className="art:w-full art:bg-background art:px-4 art:py-16 art:font-sans art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-24">
      <div className="art:mx-auto art:w-full art:max-w-4xl">
        <motion.div className="art:text-center" initial={hidden} animate={shown} transition={reduced ? { duration: 0 } : { duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: 0.05 }}>
          <p className="art:font-medium art:text-muted-foreground art:text-sm">{copy.badge}</p>
          <h2 className="art:mt-3 art:text-balance art:font-medium art:text-4xl art:leading-none art:tracking-tight">{copy.headlineAccent ? `${copy.headline} ${copy.headlineAccent}` : copy.headline}</h2>
          <p className="art:mx-auto art:mt-4 art:max-w-xl art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">{copy.subhead}</p>
        </motion.div>
        <motion.div className="art:mt-9" initial={hidden} animate={shown} transition={reduced ? { duration: 0 } : { duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: 0.15 }}>
          <div className="art:flex art:flex-col art:gap-1.5 art:w-full">
            <div data-state={focused ? "focused" : "idle"} className={`art:relative art:h-10 art:overflow-hidden art:rounded-full art:border art:bg-background art:transition-colors art:duration-200 ${focused ? "art:border-foreground/60" : "art:border-border"}`}>
              <span className="art:pointer-events-none art:absolute art:left-3 art:top-1/2 art:flex art:-translate-y-1/2 art:items-center art:text-muted-foreground art:[&_svg]:h-4 art:[&_svg]:w-4">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-search art:size-4" aria-hidden="true"><path d="m21 21-4.34-4.34"/><circle cx="11" cy="11" r="8"/></svg>
              </span>
              <input ref={inputRef} id={inputId} type="search" placeholder={copy.search.placeholder} aria-label="Search frequently asked questions" className="art:peer art:h-full art:w-full art:bg-transparent art:text-sm art:leading-6 art:caret-foreground art:outline-none art:pr-14 art:pl-13 art:text-foreground art:placeholder:text-muted-foreground" value={query} onChange={event => setQuery(event.target.value)} onFocus={() => setFocused(true)} onBlur={() => setFocused(false)}/>
              {query && <span className="art:absolute art:right-0 art:top-0 art:flex art:h-full art:items-center art:text-muted-foreground art:[&_button]:grid art:[&_button]:size-10 art:[&_button]:place-items-center art:[&_svg]:h-4 art:[&_svg]:w-4">
                <button type="button" className="art:items-center art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:font-normal art:absolute art:top-1/2 art:right-3 art:grid art:size-10 art:-translate-y-1/2 art:place-items-center art:text-muted-foreground art:transition-[color,background-color,box-shadow] art:duration-200 art:ease-out art:hover:bg-muted art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-1 art:focus-visible:ring-ring/30 art:rounded-full" aria-label="Clear search" tabIndex={0} onClick={event => { setQuery(""); inputRef.current?.blur(); event.currentTarget.blur(); }}>
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-x art:size-4" aria-hidden="true"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
                </button>
              </span>}
            </div>
            <div className="art:contents"/>
          </div>
          {topics.length ? <div className="art:mt-4 art:overflow-x-auto art:text-center">
            <ArtemisSegmentedTabs items={[{ value: ALL, label: copy.search.allLabel }, ...topics.map(value => ({ value, label: value }))]} value={topic} onValueChange={setTopic} listClassName="art:inline-flex art:items-center art:gap-1 art:rounded-full art:bg-muted art:p-1 art:min-w-max" ariaLabel="Filter questions by topic"/>
          </div> : null}
        </motion.div>
        <motion.div className="art:mt-8" initial={hidden} animate={shown} transition={reduced ? { duration: 0 } : { duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: 0.25 }}>
          <AnimatePresence mode="wait" initial={false}>
            <motion.div key={`${topic}:${search}`} initial={reduced ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={reduced ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, y: -6, transition: { duration: 0.22, ease: ARTEMIS_EASE_OUT } }} transition={reduced ? { duration: 0 } : { duration: 0.2, ease: ARTEMIS_EASE_OUT }}>
              {filtered.length ? <SearchAccordion items={filtered}/> : <div className="art:border art:border-border art:bg-background art:px-6 art:py-12 art:text-center"><p className="art:font-medium art:text-xl">{copy.search.emptyTitle}</p><p className="art:mt-2 art:text-muted-foreground art:text-sm">{copy.search.emptyText}</p></div>}
            </motion.div>
          </AnimatePresence>
        </motion.div>
      </div>
    </section>);
}

"use client";
// @zeus-internal
import { motion, useReducedMotion } from "motion/react";
import { ChevronDown } from "lucide-react";
import { useId, useState } from "react";
import type { ArtemisFaqQuestion } from "../../content";
type FaqItem = ArtemisFaqQuestion & { id: string };
function Answer({ item, expanded, separatedAbove, separatedBelow, topGap, toggle, group }: { item: FaqItem; expanded: boolean; separatedAbove: boolean; separatedBelow: boolean; topGap: boolean; toggle: () => void; group: string }) {
  const reduced = useReducedMotion() === true;
  const trigger = `${group}-${item.id}`, region = `${trigger}-answer`;
  const rowMotion = reduced ? { duration: 0 } : { type: "spring", duration: 0.55, bounce: 0.38 } as const;
  return <motion.div initial={false} animate={{ marginTop: topGap ? 12 : 0 }} transition={rowMotion}>
    <motion.div className="art:overflow-hidden art:bg-card art:text-card-foreground" initial={false} animate={{ borderTopLeftRadius: separatedAbove ? 28 : 0, borderTopRightRadius: separatedAbove ? 28 : 0, borderBottomLeftRadius: separatedBelow ? 28 : 0, borderBottomRightRadius: separatedBelow ? 28 : 0 }} transition={rowMotion}>
      <button type="button" id={trigger} aria-expanded={expanded} aria-controls={region} onClick={toggle} className="art:flex art:min-h-[58px] art:w-full art:items-center art:gap-4 art:px-5 art:text-left art:outline-none art:transition-colors art:hover:bg-muted/60 art:focus-visible:bg-muted/25">
        <span className="art:flex art:min-w-0 art:flex-1 art:flex-col art:gap-1 art:@min-[640px]/artemis:flex-row art:@min-[640px]/artemis:items-center art:@min-[640px]/artemis:justify-between art:@min-[640px]/artemis:gap-4">
          <span className="art:text-[15px] art:font-medium art:text-foreground">{item.question}</span>
          {item.category ? <span className="art:shrink-0 art:text-xs art:font-normal art:tracking-[0.1em] art:text-muted-foreground art:uppercase">{item.category}</span> : null}
        </span>
        <motion.span aria-hidden="true" className="art:grid art:size-6 art:shrink-0 art:place-items-center art:text-muted-foreground" animate={{ rotate: expanded ? 180 : 0 }} transition={reduced ? { duration: 0 } : { type: "spring", duration: 0.42, bounce: 0.28 }}><ChevronDown className="art:size-4"/></motion.span>
      </button>
      <motion.section id={region} aria-labelledby={trigger} aria-hidden={!expanded} className="art:overflow-hidden" initial={false} animate={{ height: expanded ? "auto" : 0 }} transition={reduced ? { duration: 0 } : { type: "spring", duration: expanded ? 0.58 : 0.46, bounce: expanded ? 0.32 : 0.26 }}>
        <motion.div className="art:px-5 art:pb-5 art:text-sm art:leading-6 art:text-muted-foreground" initial={false} animate={{ opacity: expanded ? 1 : 0 }} transition={{ duration: reduced ? 0 : 0.18, ease: [0.16, 1, 0.3, 1] }}>{item.answer}</motion.div>
      </motion.section>
    </motion.div>
  </motion.div>;
}
export function SearchAccordion({ items }: { items: readonly FaqItem[] }) {
  const group = useId();
  const [selected, setSelected] = useState<string | null>(() => items[0]?.id ?? null);
  const index = items.findIndex(item => item.id === selected);
  return <div className="art:w-full">{items.map((item, position) => <Answer key={item.id} item={item} group={group} expanded={selected === item.id} topGap={position > 0 && (position === index || position === index + 1)} separatedAbove={position === 0 || position === index || position === index + 1} separatedBelow={position === items.length - 1 || position === index || position === index - 1} toggle={() => setSelected(current => current === item.id ? null : item.id)}/>)}</div>;
}
